const clothes=['#4a626c','#6b4248','#72735c','#455c50','#9b8c74','#4d5366','#a3a3a0'];
const skins=['#d4ac8b','#b78260','#8c5d43','#e4c3a3','#674733'];
const hairs=['#302823','#4b3930','#8b7755','#59534c','#b3aba0'];
